const REACT_ITEMS = REACTIONS.map(([r, right, w1, w2, w3, lv, why]) => mk(+lv, 'reactions of amines', `The main organic product of ${F(r)} is`, F(right), [F(w1), F(w2), F(w3)], S(why, `Product: <b>${F(right)}</b>.`), +lv >= 3 ? 'Check which N&ndash;H count and which medium decide the product.' : ''));

// 3. tests: compound | formula | flags | kind.  c carbylamine, n N2 gas with cold nitrous acid, z azo dye with b-naphthol, h sulphonamide soluble in alkali,
//    i sulphonamide insoluble in alkali, y gives an amide with ethanoyl chloride, d dissolves in dilute HCl
const CMP = [
  ['ethylamine', 'CH3CH2NH2', 'cnhyd', 'primary aliphatic amine'],
  ['methylamine', 'CH3NH2', 'cnhyd', 'primary aliphatic amine'],
  ['propan-2-amine', '(CH3)2CHNH2', 'cnhyd', 'primary aliphatic amine'],
  ['benzylamine', 'C6H5CH2NH2', 'cnhyd', 'primary aliphatic amine (the NH2 is on a CH2, not on the ring)'],
  ['aniline', 'C6H5NH2', 'czhyd', 'primary aromatic amine'],
  ['p-toluidine', 'p-CH3C6H4NH2', 'czhyd', 'primary aromatic amine'],
  ['diethylamine', '(C2H5)2NH', 'iyd', 'secondary amine'],
  ['dimethylamine', '(CH3)2NH', 'iyd', 'secondary amine'],
  ['N-methylaniline', 'C6H5NHCH3', 'iyd', 'secondary aromatic amine'],
  ['triethylamine', '(C2H5)3N', 'd', 'tertiary amine (no N&ndash;H)'],
  ['trimethylamine', '(CH3)3N', 'd', 'tertiary amine (no N&ndash;H)'],
  ['N,N-dimethylaniline', 'C6H5N(CH3)2', 'd', 'tertiary aromatic amine (no N&ndash;H)'],
  ['acetanilide', 'CH3CONHC6H5', '', 'an amide: the N lone pair is tied up with C=O, so it is not basic'],
  ['benzamide', 'C6H5CONH2', '', 'an amide (not basic)'],
  ['nitrobenzene', 'C6H5NO2', '', 'a nitro compound (no basic nitrogen)'],
  ['ethanol', 'CH3CH2OH', '', 'an alcohol (no nitrogen)'],
].map(([n, f, fl, k]) => ({ n, f, fl, k, lab: `${F(f)} (${n})` }));
const TESTS = [
  { t: 'd', lv: 1, name: 'a clear solution when shaken with dilute HCl (it dissolves because it is basic)', rule: 'Amines are basic and form soluble ammonium chlorides. Amides, nitro compounds and alcohols are not basic enough to dissolve.' },
  { t: 'c', lv: 2, name: 'the carbylamine test (a foul smell with CHCl3 and alcoholic KOH)', rule: 'The carbylamine test needs a primary amine: RNH<sub>2</sub> or ArNH<sub>2</sub> (two N&ndash;H bonds).' },
  { t: 'y', lv: 2, name: 'an amide on reaction with ethanoyl chloride', rule: 'Acylation needs an N&ndash;H bond to lose: primary and secondary amines react; tertiary amines cannot form a stable amide.' },
  { t: 'n', lv: 3, name: 'effervescence of N2 when cold nitrous acid is added', rule: 'Only primary aliphatic amines (including benzylamine) give an unstable diazonium ion that loses N<sub>2</sub> at once.' },
  { t: 'z', lv: 3, name: 'a scarlet-red azo dye when treated with cold nitrous acid and then alkaline &beta;-naphthol', rule: 'Only primary aromatic amines form a stable diazonium salt that couples with &beta;-naphthol.' },
  { t: 'h', lv: 3, name: 'a sulphonamide that dissolves in aqueous alkali with benzenesulphonyl chloride', rule: 'Hinsberg: a primary amine gives RNH&ndash;SO<sub>2</sub>Ph with an acidic N&ndash;H, so it dissolves in alkali.' },
  { t: 'i', lv: 3, name: 'an alkali-insoluble sulphonamide with benzenesulphonyl chloride', rule: 'Hinsberg: a secondary amine gives R<sub>2</sub>N&ndash;SO<sub>2</sub>Ph with no N&ndash;H, so it is insoluble in alkali.' },
];
const TEST_ITEMS = [];
for (const T of TESTS) {
  const Pp = CMP.filter((c) => c.fl.includes(T.t)), Nn = CMP.filter((c) => !c.fl.includes(T.t));
  const more = (arr, start, step, k, skip = []) => { const out = []; for (let i = 0; out.length < k && i < 200; i++) { const c = arr[(start + i * step) % arr.length]; if (!out.includes(c) && !skip.includes(c)) out.push(c); } for (const c of arr) { if (out.length >= k) break; if (!out.includes(c) && !skip.includes(c)) out.push(c); } return out; };
  const why = (c) => `${c.lab}: ${c.k}`;
  const kpos = Math.min(6, Pp.length + 1);
  for (let j = 0; j < kpos; j++) {
    const right = Pp[(j * 3 + 1) % Pp.length]; const wr = more(Nn, j * 2 + 1, 5, 3);
    TEST_ITEMS.push(mk(T.lv, 'tests for amines', `Which of the following gives ${T.name}?`, right.lab, wr.map((c) => c.lab), S(T.rule, `<b>${why(right)}</b>: it fits.`, `Not suitable: ${wr.map(why).join('; ')}.`)));
  }
  for (let j = 0; j < 2; j++) {
    const right = Nn[(j * 4 + 2) % Nn.length]; const wr = more(Pp, j + 1, 2, 3);
    TEST_ITEMS.push(mk(T.lv + (j ? 1 : 0), 'tests for amines', `Which of the following does NOT give ${T.name}?`, right.lab, wr.map((c) => c.lab), S(T.rule, `<b>${why(right)}</b>: it does not fit.`, `The others do: ${wr.map(why).join('; ')}.`), 'A &ldquo;does NOT&rdquo; question: three options are positive and one is negative.'));
  }
}
for (const T of TESTS.filter((x) => 'cnzh'.includes(x.t))) {
  const diff = [], same = [];
  for (let a = 0; a < CMP.length; a++) for (let b = a + 1; b < CMP.length; b++) { const A = CMP[a], B = CMP[b]; (A.fl.includes(T.t) !== B.fl.includes(T.t) ? diff : same).push([A, B]); }
  const nm = { c: 'the carbylamine test', n: 'cold nitrous acid (N<sub>2</sub> gas)', z: 'the &beta;-naphthol azo dye test', h: 'benzenesulphonyl chloride and aqueous KOH (soluble sulphonamide)' }[T.t];
  for (let j = 0; j < 3; j++) {
    const right = diff[(j * 37 + 5) % diff.length]; const ws = []; for (let i = 0; ws.length < 3 && i < 300; i++) { const w = same[(j * 11 + i * 17 + 3) % same.length]; if (!ws.includes(w)) ws.push(w); }
    const pr = (p) => `${p[0].lab} and ${p[1].lab}`; const res = (p) => `${p[0].n}: ${p[0].fl.includes(T.t) ? 'positive' : 'negative'}, ${p[1].n}: ${p[1].fl.includes(T.t) ? 'positive' : 'negative'}`;
    TEST_ITEMS.push(mk(3, 'distinguishing tests', `Which pair can be distinguished by ${nm}?`, pr(right), ws.map(pr), S(T.rule, `<b>${res(right)}</b>: they differ, so the test separates them.`, `Other pairs behave the same: ${ws.map(res).join('; ')}.`)));
  }
}

// 4. bases ranked by pKb (strongest first)
const BASES = [
  ['Methylamines in water', 'in water the order is set by the +I effect, solvation of the ammonium ion (more N&ndash;H, better solvation) and crowding', [['(CH3)2NH', 3.27], ['CH3NH2', 3.38], ['(CH3)3N', 4.22], ['NH3', 4.75]], 2],
  ['Ethylamines in water', 'the same three effects: the 2&deg; amine wins, then the 3&deg; amine (larger +I), then the 1&deg;, then ammonia', [['(C2H5)2NH', 3.00], ['(C2H5)3N', 3.25], ['C2H5NH2', 3.29], ['NH3', 4.75]], 3],
  ['Para-substituted anilines', 'OCH<sub>3</sub> and CH<sub>3</sub> donate electrons (more basic); NO<sub>2</sub> withdraws them (less basic)', [['p-CH3OC6H4NH2', 8.70], ['p-CH3C6H4NH2', 8.92], ['C6H5NH2', 9.38], ['p-O2NC6H4NH2', 13.0]], 3],
  ['Aliphatic and aromatic amines', 'an alkyl group donates electrons; the phenyl group withdraws and the ring takes part in resonance with the aniline lone pair; benzylamine is insulated by a CH<sub>2</sub>', [['CH3NH2', 3.38], ['C6H5CH2NH2', 4.67], ['NH3', 4.75], ['C6H5NH2', 9.38]], 2],
  ['N-substituted anilines', 'alkyl groups on nitrogen donate electrons, while a second phenyl ring draws the lone pair away', [['C6H5N(CH3)2', 8.85], ['C6H5NHCH3', 9.15], ['C6H5NH2', 9.40], ['(C6H5)2NH', 13.2]], 4],
  ['Nitroanilines', 'a nitro group lowers basicity most at the ortho position (nearest) and also at para (resonance); the meta effect is only inductive', [['C6H5NH2', 9.40], ['m-O2NC6H4NH2', 11.5], ['p-O2NC6H4NH2', 13.0], ['o-O2NC6H4NH2', 14.3]], 4],
  ['Chloroanilines', 'chlorine withdraws electrons by the &minus;I effect, most strongly when close to NH<sub>2</sub>', [['C6H5NH2', 9.40], ['p-ClC6H4NH2', 10.0], ['m-ClC6H4NH2', 10.5], ['o-ClC6H4NH2', 11.4]], 4],
  ['Toluidines', 'the methyl group donates electrons; at the ortho position crowding opposes solvation and the isomer is weaker than aniline', [['p-CH3C6H4NH2', 8.92], ['m-CH3C6H4NH2', 9.31], ['C6H5NH2', 9.40], ['o-CH3C6H4NH2', 9.61]], 5],
  ['Nitrogen compounds of different types', 'an amine lone pair is strongest when localised and pushed by alkyl groups; an amide lone pair is delocalised into C=O, so it is hardly basic', [['(CH3)2NH', 3.27], ['NH3', 4.75], ['C6H5NH2', 9.40], ['CH3CONH2', 14.5]], 3],
  ['Amines with different groups', 'electron donation raises basicity, resonance and electron withdrawal lower it', [['(CH3)2NH', 3.27], ['C6H5CH2NH2', 4.67], ['C6H5NH2', 9.40], ['p-O2NC6H4NH2', 13.0]], 3],
];
const BASE_ITEMS = [];
for (const [title, why, list, lv] of BASES) {
  const tab = list.map((x) => `${F(x[0])} (pK<sub>b</sub> ${x[1]})`).join('; ');
  const shuffled = [list[2], list[0], list[3], list[1]];
  const qlist = shuffled.map((x, i) => `(${'abcd'[i]}) ${F(x[0])}`).join(', ');
  const L = (x) => 'abcd'[shuffled.indexOf(x)];
  BASE_ITEMS.push(mk(lv, 'basicity of amines', `${title}: which is the strongest base? ${qlist}.`, `(${L(list[0])}) ${F(list[0][0])}`, [list[1], list[2], list[3]].map((x) => `(${L(x)}) ${F(x[0])}`), S(`Compare how available the N lone pair is and how stable the conjugate acid is: ${why}.`, `pK<sub>b</sub> values: ${tab}. The smallest pK<sub>b</sub> is the strongest base: <b>${F(list[0][0])}</b>.`), 'A smaller pK<sub>b</sub> means a stronger base.'));
  BASE_ITEMS.push(mk(lv, 'basicity of amines', `${title}: which is the weakest base? ${qlist}.`, `(${L(list[3])}) ${F(list[3][0])}`, [list[0], list[1], list[2]].map((x) => `(${L(x)}) ${F(x[0])}`), S(`Compare how available the N lone pair is and how stable the conjugate acid is: ${why}.`, `pK<sub>b</sub> values: ${tab}. The largest pK<sub>b</sub> is the weakest base: <b>${F(list[3][0])}</b>.`), 'A larger pK<sub>b</sub> means a weaker base.'));
  BASE_ITEMS.push(ord(lv + (lv < 4 ? 1 : 0), 'basicity of amines', `${title}: the correct order of increasing basic strength for ${qlist.replace(/\(.\) /g, '')} is`, [...list].reverse().map((x) => F(x[0])), ' &lt; ', S(`Basic strength follows the availability of the lone pair and the stability of the cation: ${why}.`, `pK<sub>b</sub> values: ${tab}.`, `Increasing basic strength means decreasing pK<sub>b</sub>: ${[...list].reverse().map((x) => F(x[0])).join(' &lt; ')}.`), 'Increasing strength: weakest first.'));
}

